        link.href = cssUrl;
        link.onload = () => {
            link.dataset.state = "loaded";
            link.dispatchEvent(new Event("assetLoaded"));
            cssResolve();
        };
        link.onerror = () => {
            link.dataset.state = "failed";
            link.dispatchEvent(new Event("assetFailed"));
